function greatestTail(s: string): string {
  const n = s.length;
  let i = 0, j = 1, k = 0;
  while (j + k < n) {
    const a = s[i + k], b = s[j + k];
    if (a === b) {
      k++;
    } else if (a < b) {
      i = Math.max(i + k + 1, j);
      j = i + 1;
      k = 0;
    } else {
      j = j + k + 1;
      k = 0;
    }
  }
  return s.slice(i);
}

