class Solution:
    def greatestTail(self, s: str) -> str:
        n = len(s)
        i, j, k = 0, 1, 0
        while j + k < n:
            a, b = s[i + k], s[j + k]
            if a == b:
                k += 1
            elif a < b:
                i = max(i + k + 1, j)
                j, k = i + 1, 0
            else:
                j, k = j + k + 1, 0
        return s[i:]

